const useAPIToken = `-- name: UseAPIToken :one
UPDATE api_tokens SET last_used_at = now()
WHERE token_hash = $1
RETURNING user_id
`

// Resolves a token and records its use in one statement, so authenticating a
// request costs one round trip.
func (q *Queries) UseAPIToken(ctx context.Context, tokenHash []byte) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, useAPIToken, tokenHash)
	var user_id uuid.UUID
	err := row.Scan(&user_id)
	return user_id, err
}
